const fs=require('fs');const rows=JSON.parse(fs.readFileSync(0,'utf8'));
const out=rows.map(c=>{const x=c.inputs;
 if(c.candidate_id==='arena_stat60_v1'){
  let bg=Math.fround(x.base_stat*.01),g=bg+x.raw_iv*.005;
  let raw=Math.fround((x.stat==='hp'?170:110)*g+(x.stat==='hp'?70:10));
  let core=Math.round(raw),v=Math.round(core*x.nature_multiplier+(x.stat==='hp'?100:50));
  return {value:v,trace:{base_growth_f32:bg,growth:g,core_f32:raw,core:core}};
 }
 if(c.candidate_id==='showdown_non_hp_stat60_v1'){
  let scaled=1.1*(x.base_stat+3*x.display_iv),rounded=Math.round(scaled),core=rounded+10;
  return {value:Math.round(core*x.nature_multiplier)+50,trace:{scaled_base:scaled,rounded_scaled_base:rounded,core:core}};
 }
 let coeff=37/41, q=x.effective_power*x.multiplier;
 let raw=c.candidate_id==='arena_documented_damage60_v1'?x.attack*x.effective_power*x.multiplier*coeff:x.attack*Math.round(q)*coeff;
 let num=Math.round(raw),div=num/x.defense;
 return {value:Math.floor(div),trace:{numerator_unrounded:raw,numerator_rounded:num,quotient:div}};
});process.stdout.write(JSON.stringify(out));
